/* Derived practice: schema design, isolated from the module's seeded tables. */
const BUILD_DEFS=[
 ['departments','Create the departments table','CREATE TABLE departments (dept_code VARCHAR(10) PRIMARY KEY, dept_name VARCHAR(80) NOT NULL);','Which column identifies a department even when two departments have the same name?'],
 ['students','Create the students table','CREATE TABLE students (student_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(80) NOT NULL, dept_code VARCHAR(10) NULL, CONSTRAINT fk_student_department FOREIGN KEY (dept_code) REFERENCES departments(dept_code));','Use AUTO_INCREMENT for the student number. A foreign key checks whether a supplied department exists; NULL allows an unassigned department.'],
 ['courses','Create the courses table','CREATE TABLE courses (course_code VARCHAR(12) PRIMARY KEY, title VARCHAR(100) NOT NULL, dept_code VARCHAR(10) NOT NULL, CONSTRAINT fk_course_department FOREIGN KEY (dept_code) REFERENCES departments(dept_code));','A course needs a department. Use a foreign key together with NOT NULL; do not make the department column UNIQUE.'],
 ['student_profiles','Create the student_profiles table','CREATE TABLE student_profiles (student_id INT UNSIGNED PRIMARY KEY, email VARCHAR(100) NOT NULL UNIQUE, CONSTRAINT fk_profile_student FOREIGN KEY (student_id) REFERENCES students(student_id));','A column can be both a primary key and a foreign key. UNIQUE prevents the same email from appearing in two profiles.'],
 ['staff','Create the staff table','CREATE TABLE staff (staff_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(80) NOT NULL, manager_id INT UNSIGNED NULL, CONSTRAINT fk_staff_manager FOREIGN KEY (manager_id) REFERENCES staff(staff_id));','The manager number refers to another row in staff. Match its integer type to staff_id and allow NULL for a staff member with no manager.'],
 ['course_offerings','Create the course_offerings table','CREATE TABLE course_offerings (course_code VARCHAR(12), term VARCHAR(12), staff_id INT UNSIGNED NULL, PRIMARY KEY (course_code, term), CONSTRAINT fk_offering_course FOREIGN KEY (course_code) REFERENCES courses(course_code), CONSTRAINT fk_offering_staff FOREIGN KEY (staff_id) REFERENCES staff(staff_id));','A primary key may contain more than one column. A course code alone cannot identify an offering when the course runs in several terms.'],
 ['enrollments','Create the enrollments table','CREATE TABLE enrollments (student_id INT UNSIGNED, course_code VARCHAR(12), term VARCHAR(12), grade DECIMAL(5,2) NULL, PRIMARY KEY (student_id, course_code, term), CONSTRAINT fk_enrollment_student FOREIGN KEY (student_id) REFERENCES students(student_id), CONSTRAINT fk_enrollment_offering FOREIGN KEY (course_code, term) REFERENCES course_offerings(course_code, term));','Use one primary key containing the columns that identify an enrollment. The offering reference must check the course code and term together.']
];
