const BUILD_JOIN=`SELECT s.full_name, c.title, e.term, e.grade
FROM enrollments AS e
JOIN students AS s ON e.student_id = s.student_id
JOIN course_offerings AS o ON e.course_code = o.course_code AND e.term = o.term
JOIN courses AS c ON o.course_code = c.course_code
ORDER BY s.student_id, c.course_code;`;
